INSERT INTO zj_health(id,version,createdAt,updatedAt,deleted,title,topic,body,sourceUrl,reviewedAt,derivedJson) VALUES
('a1000000-0000-4000-8000-000000000001',1,NOW(6),NOW(6),FALSE,'烟盒成分数字怎样读','SMOKING','焦油、烟气烟碱和一氧化碳属于包装标示或特定检测条件下的烟气产量。按根数折算的合计不是人体吸收量，也不是体内残留量。不同标示或检测方法的数据应分开看。','https://www.cancer.gov/about-cancer/causes-prevention/risk/tobacco/light-cigarettes-fact-sheet','2026-10-21',JSON_OBJECT()),
('a1000000-0000-4000-8000-000000000002',1,NOW(6),NOW(6),FALSE,'减少吸烟时，给自己一点空间','SMOKING','尼古丁会形成依赖，减少吸烟可能不容易。记录可以帮助你看见常见的时间和场景。愿意的话，下次想抽时先等一会儿。低焦油标示不能证明某种香烟更安全。','https://www.cancerresearchuk.org/about-cancer/causes-of-cancer/smoking-and-cancer/whats-in-a-cigarette','2026-10-21',JSON_OBJECT()),
('a1000000-0000-4000-8000-000000000003',1,NOW(6),NOW(6),FALSE,'酒精估算保留不确定性','ALCOHOL','酒精代谢因人而异，身高体重无法单独决定消除速度。这里的结果是基于记录和参数的情景估算，不是检测值，也不能保证某个时间已经完全代谢。','https://www.niaaa.nih.gov/publications/alcohol-metabolism','2026-10-21',JSON_OBJECT()),
('a1000000-0000-4000-8000-000000000004',1,NOW(6),NOW(6),FALSE,'不要用估算结果决定驾驶时间','ALCOHOL','模型曲线接近零不等于已经清醒或具备驾驶能力。饮酒后不要根据本工具判断何时能够开车。继续追加饮酒前，可以先考虑到这里结束，给今晚留一些休息时间。','https://www.nhtsa.gov/risky-driving/drunk-driving','2026-10-21',JSON_OBJECT()),
('a1000000-0000-4000-8000-000000000005',1,NOW(6),NOW(6),FALSE,'照顾感受与休息','INTIMACY','自慰本身不因次数被定义为疾病或失败。更值得留意的是自己的意愿、舒适程度，以及是否影响睡眠、工作或生活。想释放一下可以理解，如果已经疲惫或不适，就先休息。','https://www.plannedparenthood.org/learn/sex-pleasure-and-sexual-dysfunction/masturbation/masturbation-healthy','2026-10-21',JSON_OBJECT());
